<?php
declare(strict_types=1);

function store_option(string $name): mixed {
    $r=row('SELECT option_value FROM wp_options WHERE option_name=?',[$name]);
    if(!$r) return null;
    $v=@unserialize($r['option_value'],['allowed_classes'=>false]);
    return $v===false && $r['option_value']!=='b:0;' ? $r['option_value'] : $v;
}
function store_put_option(string $name,mixed $value): void {
    $raw=is_array($value)?serialize($value):(string)$value;
    $r=row('SELECT option_id FROM wp_options WHERE option_name=? FOR UPDATE',[$name]);
    if($r) exec_sql('UPDATE wp_options SET option_value=? WHERE option_id=?',[$raw,$r['option_id']]);
    else exec_sql("INSERT INTO wp_options(option_name,option_value,autoload) VALUES (?,?,'yes')",[$name,$raw]);
}
function store_tab_labels(): array { return ['general'=>'General','products'=>'Products','tax'=>'Tax','shipping'=>'Shipping','payments'=>'Payments','account'=>'Accounts & Privacy','email'=>'Emails','integration'=>'Integration','site-visibility'=>'Site visibility','point-of-sale'=>'Point of Sale','woocs'=>'Currency','advanced'=>'Advanced','order-statuses'=>'Order Statuses']; }
function store_tab_route(string $key): string { return match($key){'general'=>'/admin/woocommerce/settings','shipping'=>'/admin/woocommerce/shipping','payments'=>'/admin/woocommerce/payments','tax'=>'/admin/woocommerce/settings?tab=tax','order-statuses'=>'/admin/woocommerce/order-statuses',default=>'/admin/woocommerce/settings?tab='.$key}; }
function store_tabs(string $active): void { ?><nav class="store-tabs" aria-label="Store settings"><?php foreach(store_tab_labels() as $key=>$label): ?><a class="<?=$active===$key?'active':''?>" href="<?=h(path(store_tab_route($key)))?>"><?=h($label)?></a><?php endforeach; ?></nav><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php }
function store_header(string $title,string $tab): void { ?><div class="store-head"><h1><?=h($title)?></h1><p>Store settings from the commerce database</p></div><?php store_tabs($tab); if($tab==='advanced' && str_starts_with((string)($_SERVER['REQUEST_URI']??''),path('/admin/woocommerce/settings'))) woo_advanced_nav('page'); }
function store_gateway_ids(): array {
    $names=rows("SELECT option_name FROM wp_options WHERE option_name LIKE 'woocommerce_%_settings'");
    $exclude=['google_analytics','maxmind_geolocation']; $out=[];
    foreach($names as $r) {
        if(!preg_match('/^woocommerce_([a-z0-9_]+)_settings$/',$r['option_name'],$m)) continue;
        $id=$m[1];
        if(in_array($id,$exclude,true) || preg_match('/^(customer_|flat_rate_|free_shipping_|local_pickup_|wc_order_status_email_|wwlc_email_|new_order$|failed_order$|cancelled_order$)/',$id)) continue;
        $data=store_option($r['option_name']);
        if(is_array($data) && array_key_exists('enabled',$data)) $out[]=$id;
    }
    return $out;
}
function admin_store_payments(): void {
    $ids=store_gateway_ids(); $items=[];
    foreach($ids as $id) { $v=store_option('woocommerce_'.$id.'_settings'); $items[]=['id'=>$id,'title'=>$v['title'] ?: ucwords(str_replace('_',' ',$id)),'enabled'=>($v['enabled']??'no')==='yes']; }
    $order=store_option('woocommerce_gateway_order'); if(is_array($order)) usort($items,static fn($a,$b)=>(int)($order[$a['id']]??999)<=>(int)($order[$b['id']]??999));
    admin_layout('Payments',static function() use($items){ store_header('Payments','payments'); ?><div class="store-card"><table class="store-table"><thead><tr><th>Payment method</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><strong><?=h($i['title'])?></strong><small><?=h($i['id'])?></small></td><td><span class="store-state <?=$i['enabled']?'on':'off'?>"><?=$i['enabled']?'Enabled':'Disabled'?></span></td><td><a class="secondary" href="<?=h(path('/admin/woocommerce/payment?id='.rawurlencode($i['id'])))?>">Manage</a></td></tr><?php endforeach; ?></tbody></table></div><p class="store-help">Gateway credentials are stored in the imported database and remain hidden on this page. Checkout processing needs a separate integration before enabling live payments.</p><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function admin_store_payment(): void {
    $id=(string)($_GET['id']??''); if(!in_array($id,store_gateway_ids(),true)) {http_response_code(404);exit('Payment method not found.');}
    $v=store_option('woocommerce_'.$id.'_settings');
    admin_layout('Payment method',static function() use($id,$v){store_header(ucwords(str_replace('_',' ',$id)),'payments'); ?><form class="store-card store-form" method="post" action="<?=h(path('/admin/woocommerce/payment'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=h($id)?>"><label class="store-check"><input type="checkbox" name="enabled" value="yes" <?=($v['enabled']??'no')==='yes'?'checked':''?>> Enable this payment method</label><?php foreach(['title'=>'Title','description'=>'Description','instructions'=>'Instructions'] as $key=>$label): ?><label><?=h($label)?><?php if($key==='title'): ?><input name="<?=h($key)?>" value="<?=h($v[$key]??'')?>" maxlength="190"><?php else: ?><textarea name="<?=h($key)?>" rows="4" maxlength="3000"><?=h($v[$key]??'')?></textarea><?php endif; ?></label><?php endforeach; ?><div class="store-actions"><button class="primary">Save changes</button><a class="secondary" href="<?=h(path('/admin/woocommerce/payments'))?>">Back to payments</a></div></form><p class="store-help">This page preserves all other settings, including stored credentials and gateway specific options.</p><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function save_store_payment(): never {
    $id=(string)($_POST['id']??'');if(!in_array($id,store_gateway_ids(),true)){http_response_code(400);exit('Invalid payment method.');}
    $name='woocommerce_'.$id.'_settings';$old=store_option($name);if(!is_array($old)){http_response_code(400);exit('Invalid settings.');}
    $new=$old;$new['enabled']=isset($_POST['enabled'])?'yes':'no';
    foreach(['title'=>190,'description'=>3000,'instructions'=>3000] as $key=>$max){$value=trim((string)($_POST[$key]??''));if(mb_strlen($value)>$max){notice('A field is too long.');redirect('/admin/woocommerce/payment?id='.rawurlencode($id));}$new[$key]=$value;}
    db()->beginTransaction();try{store_put_option($name,$new);audit_change('payment_gateway',0,'update',['gateway'=>$id,'enabled'=>$old['enabled']??'no'],['gateway'=>$id,'enabled'=>$new['enabled']]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}
    notice('Payment settings saved.');redirect('/admin/woocommerce/payment?id='.rawurlencode($id));
}
function admin_store_shipping(): void {
    $zones=rows('SELECT zone_id,zone_name,zone_order FROM wp_woocommerce_shipping_zones ORDER BY zone_order,zone_id');
    $methods=rows('SELECT instance_id,zone_id,method_id,method_order,is_enabled FROM wp_woocommerce_shipping_zone_methods ORDER BY zone_id,method_order');
    $locations=rows('SELECT zone_id,location_code,location_type FROM wp_woocommerce_shipping_zone_locations ORDER BY zone_id,location_code');
    admin_layout('Shipping',static function() use($zones,$methods,$locations){store_header('Shipping zones','shipping');store_shipping_subtabs('zones');?><div class="store-card"><table class="store-table"><thead><tr><th>Zone</th><th>Locations</th><th>Methods</th><th></th></tr></thead><tbody><?php foreach($zones as $z): ?><tr><td><strong><?=h($z['zone_name'])?></strong></td><td><?php $a=[];foreach($locations as $l)if($l['zone_id']===$z['zone_id'])$a[]=$l['location_code'];echo h(implode(', ',$a) ?: 'All locations'); ?></td><td><?php foreach($methods as $m)if($m['zone_id']===$z['zone_id'])echo '<span class="store-method">'.h(str_replace('_',' ',$m['method_id'])).'</span> '; ?></td><td><a class="secondary" href="<?=h(path('/admin/woocommerce/zone?id='.$z['zone_id']))?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div><h2>Locations outside your other zones</h2><div class="store-card"><?php foreach($methods as $m): if((int)$m['zone_id']===0): ?><p><?=h(str_replace('_',' ',$m['method_id']))?> · <a href="<?=h(path('/admin/woocommerce/method?id='.$m['instance_id']))?>">Edit method</a></p><?php endif; endforeach; ?></div><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function admin_store_zone(): void {
    $id=(int)($_GET['id']??0);$z=row('SELECT * FROM wp_woocommerce_shipping_zones WHERE zone_id=?',[$id]);if(!$z){http_response_code(404);exit('Zone not found.');}
    $methods=rows('SELECT * FROM wp_woocommerce_shipping_zone_methods WHERE zone_id=? ORDER BY method_order',[$id]);$loc=rows('SELECT location_code,location_type FROM wp_woocommerce_shipping_zone_locations WHERE zone_id=?',[$id]);
    admin_layout('Shipping zone',static function() use($z,$methods,$loc,$id){store_header('Edit shipping zone','shipping');?><form class="store-card store-form" method="post" action="<?=h(path('/admin/woocommerce/zone'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Zone name<input name="name" value="<?=h($z['zone_name'])?>" maxlength="200" required></label><label>Zone regions <small>One country, state or postcode per line. Format: country:CH, state:CH:ZH, postcode:8000</small><textarea name="locations" rows="5"><?php foreach($loc as $l)echo h($l['location_type'].':'.$l['location_code'])."\n"; ?></textarea></label><button class="primary">Save zone</button></form><h2>Shipping methods</h2><div class="store-card"><table class="store-table"><thead><tr><th>Method</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($methods as $m): ?><tr><td><?=h(str_replace('_',' ',$m['method_id']))?></td><td><?=$m['is_enabled']?'Enabled':'Disabled'?></td><td><a href="<?=h(path('/admin/woocommerce/method?id='.$m['instance_id']))?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function save_store_zone(): never {
    $id=(int)($_POST['id']??0);$old=row('SELECT * FROM wp_woocommerce_shipping_zones WHERE zone_id=?',[$id]);if(!$old){http_response_code(404);exit('Zone not found.');}
    $name=trim((string)($_POST['name']??''));$lines=preg_split('/\R/',trim((string)($_POST['locations']??'')))?:[];$locations=[];
    if($name===''||mb_strlen($name)>200||count($lines)>200){notice('Check the zone name and regions.');redirect('/admin/woocommerce/zone?id='.$id);}
    foreach($lines as $line){if(trim($line)==='')continue;if(!preg_match('/^(country|state|postcode|continent):([A-Za-z0-9 :*_-]{1,120})$/',trim($line),$m)){notice('Use a valid region on each line.');redirect('/admin/woocommerce/zone?id='.$id);}$locations[]=[$id,$m[2],$m[1]];}
    db()->beginTransaction();try{exec_sql('UPDATE wp_woocommerce_shipping_zones SET zone_name=? WHERE zone_id=?',[$name,$id]);exec_sql('DELETE FROM wp_woocommerce_shipping_zone_locations WHERE zone_id=?',[$id]);foreach($locations as $l)exec_sql('INSERT INTO wp_woocommerce_shipping_zone_locations(zone_id,location_code,location_type) VALUES (?,?,?)',$l);audit_change('shipping_zone',$id,'update',['name'=>$old['zone_name']],['name'=>$name,'locations'=>count($locations)]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}
    notice('Shipping zone saved.');redirect('/admin/woocommerce/zone?id='.$id);
}
