function save_store_method(): never {
    $id=(int)($_POST['id']??0);$m=row('SELECT * FROM wp_woocommerce_shipping_zone_methods WHERE instance_id=?',[$id]);if(!$m){http_response_code(404);exit('Method not found.');}
    $name='woocommerce_'.$m['method_id'].'_'.$id.'_settings';$v=store_option($name);if(!is_array($v))$v=[];$title=trim((string)($_POST['title']??''));if(mb_strlen($title)>190){notice('Title is too long.');redirect('/admin/woocommerce/method?id='.$id);}$v['title']=$title;
    foreach(['cost'=>500,'min_amount'=>50] as $key=>$max)if(array_key_exists($key,$v)){ $value=trim((string)($_POST[$key]??''));if(mb_strlen($value)>$max){notice('A value is too long.');redirect('/admin/woocommerce/method?id='.$id);}$v[$key]=$value; }
    if(array_key_exists('tax_status',$v)){$tax=(string)($_POST['tax_status']??'');if(!in_array($tax,['taxable','none'],true)){notice('Invalid tax status.');redirect('/admin/woocommerce/method?id='.$id);}$v['tax_status']=$tax;}
    db()->beginTransaction();try{exec_sql('UPDATE wp_woocommerce_shipping_zone_methods SET is_enabled=? WHERE instance_id=?',[isset($_POST['enabled'])?1:0,$id]);store_put_option($name,$v);audit_change('shipping_method',$id,'update',['enabled'=>$m['is_enabled']],['enabled'=>isset($_POST['enabled'])?1:0]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}
    notice('Shipping method saved.');redirect('/admin/woocommerce/method?id='.$id);
}
function admin_store_taxes(): void {
