function save_store_tax_rate(): never {
    $id=(int)($_POST['id']??0);$old=$id?row('SELECT * FROM wp_woocommerce_tax_rates WHERE tax_rate_id=?',[$id]):null;if($id&&!$old){http_response_code(404);exit('Rate not found.');}
    $country=strtoupper(trim((string)($_POST['tax_rate_country']??'')));$state=strtoupper(trim((string)($_POST['tax_rate_state']??'')));$name=trim((string)($_POST['tax_rate_name']??''));$class=trim((string)($_POST['tax_rate_class']??''));$rate=trim((string)($_POST['tax_rate']??''));$priority=(int)($_POST['tax_rate_priority']??1);
    if(($country!==''&&!preg_match('/^[A-Z]{2}$/',$country))||!preg_match('/^[A-Z0-9_-]{0,30}$/',$state)||$name===''||mb_strlen($name)>200||!is_numeric($rate)||(float)$rate<0||(float)$rate>100||$priority<1||$priority>100||!preg_match('/^[a-z0-9-]{0,100}$/',$class)){notice('Check the tax rate fields.');redirect('/admin/woocommerce/tax-rate'.($id?'?id='.$id:''));}
    $locations=[];foreach(['postcodes'=>'postcode','cities'=>'city'] as $field=>$type){foreach(explode(',',(string)($_POST[$field]??'')) as $code){$code=trim($code);if($code==='')continue;if(mb_strlen($code)>100||count($locations)>200){notice('Check the tax locations.');redirect('/admin/woocommerce/tax-rate'.($id?'?id='.$id:''));}$locations[]=[$code,$type];}}
    db()->beginTransaction();try{$data=[$country,$state,number_format((float)$rate,4,'.',''),$name,$priority,isset($_POST['tax_rate_compound'])?1:0,isset($_POST['tax_rate_shipping'])?1:0,$class];if($id)exec_sql('UPDATE wp_woocommerce_tax_rates SET tax_rate_country=?,tax_rate_state=?,tax_rate=?,tax_rate_name=?,tax_rate_priority=?,tax_rate_compound=?,tax_rate_shipping=?,tax_rate_class=? WHERE tax_rate_id=?',[...$data,$id]);else{exec_sql('INSERT INTO wp_woocommerce_tax_rates(tax_rate_country,tax_rate_state,tax_rate,tax_rate_name,tax_rate_priority,tax_rate_compound,tax_rate_shipping,tax_rate_class,tax_rate_order) VALUES (?,?,?,?,?,?,?,?,0)',$data);$id=(int)db()->lastInsertId();}exec_sql('DELETE FROM wp_woocommerce_tax_rate_locations WHERE tax_rate_id=?',[$id]);foreach($locations as [$code,$type])exec_sql('INSERT INTO wp_woocommerce_tax_rate_locations(tax_rate_id,location_code,location_type) VALUES (?,?,?)',[$id,$code,$type]);audit_change('tax_rate',$id,$old?'update':'create',[],['name'=>$name,'rate'=>$rate]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}
    notice('Tax rate saved.');redirect('/admin/woocommerce/tax-rate?id='.$id);
}
